export const experimentOptions={"types": {"a": [["transverse", "Transverse"], ["longitudinal", "Longitudinal"]], "b": [["right", "Rightward travel"], ["left", "Leftward travel"]], "labels": ["Wave type", "Travel direction"], "unit": "oscillation relationship", "choices": [["perpendicular", "Perpendicular"], ["parallel", "Parallel"]]}, "properties": {"a": [["2", "2 Hz"], ["4", "4 Hz"]], "b": [["0.5", "0.5 m"], ["1", "1 m"]], "labels": ["Frequency", "Wavelength"], "unit": "m/s wave speed"}, "measure": {"a": [["0.8", "Four wavelengths span0.8 m"], ["1.2", "Four wavelengths span1.2 m"]], "b": [["5", "5 Hz"], ["10", "10 Hz"]], "labels": ["Measured four-interval length", "Source frequency"], "unit": "m/s speed"}, "reflection": {"a": [["20", "20° incidence"], ["40", "40° incidence"]], "b": [["smooth", "Smooth representative surface"], ["rough", "One rough-surface facet"]], "labels": ["Angle from local normal", "Surface comparison"], "unit": "degrees local reflection angle"}, "sound": {"a": [["10", "10 Hz"], ["1000", "1000 Hz"]], "b": [["1", "Original frequency"], ["30", "30 times frequency"]], "labels": ["Base frequency", "Multiplier"], "unit": "range classification", "choices": [["inside", "Within20–20000 Hz"], ["outside", "Outside20–20000 Hz"]]}, "detection": {"a": [["1000", "1000 m/s"], ["1500", "1500 m/s"]], "b": [["0.1", "0.1 s return"], ["0.2", "0.2 s return"]], "labels": ["Supplied speed", "Round-trip time"], "unit": "m one-way distance"}, "spectrum": {"a": [["100", "100 MHz"], ["300", "300 MHz"]], "b": [["1", "Original frequency"], ["2", "Double frequency"]], "labels": ["Frequency", "Multiplier"], "unit": "m vacuum wavelength"}, "refraction": {"a": [["slower", "Destination slower"], ["faster", "Destination faster"]], "b": [["normal", "Normal incidence"], ["oblique", "Oblique incidence"]], "labels": ["Speed comparison", "Incident direction"], "unit": "bend", "choices": [["none", "No bend"], ["toward", "Toward normal"], ["away", "Away from normal"]]}, "hazards": {"a": [["2", "2 mSv per exposure"], ["4", "4 mSv per exposure"]], "b": [["1", "One equal exposure"], ["3", "Three equal exposures"]], "labels": ["Supplied dose", "Number of equal exposures"], "unit": "mSv total"}, "applications": {"a": [["thermal", "Detect warm-surface emission"], ["internal", "Transmit through tissue for an internal image"]], "b": [["ir", "Infrared"], ["xray", "X-ray"]], "labels": ["Requirement", "Wave band"], "unit": "stated match", "choices": [["yes", "Matches the stated requirement"], ["no", "Does not match this requirement"]]}, "lenses": {"a": [["4", "Object4 mm"], ["8", "Object8 mm"]], "b": [["12", "Image12 mm"], ["24", "Image24 mm"]], "labels": ["Object height", "Supplied image height"], "unit": "magnification"}, "colour": {"a": [["red", "Red-only input"], ["blue", "Blue-only input"]], "b": [["red", "Ideal red filter"], ["blue", "Ideal blue filter"]], "labels": ["Incoming band", "Filter"], "unit": "transmitted band", "choices": [["red", "Red transmitted"], ["blue", "Blue transmitted"], ["none", "No transmitted beam"]]}, "blackbody": {"a": [["lower", "Lower-temperature spectrum"], ["higher", "Higher-temperature spectrum"]], "b": [["A", "Compare with reference A"], ["B", "Compare with reference B"]], "labels": ["Temperature comparison", "Reference label"], "unit": "peak comparison", "choices": [["longer", "Longer-wavelength peak"], ["shorter", "Shorter-wavelength peak"]]}, "infrared": {"a": [["matt", "Matt black"], ["shiny", "Shiny reflective"]], "b": [["warm", "Warm common temperature"], ["hot", "Hot common temperature"]], "labels": ["Surface", "Source condition"], "unit": "relative detector units"}};
export const tasksForWav1=(k,tier="Higher")=>wav1Tasks[k].filter(t=>!t.higher||tier==="Higher");
export const validWav1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericWav1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceWav1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;

export function experimentResult(k,a,b){const o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');const x=Number(a),y=Number(b);let value;
if(k==='types')value=a==='transverse'?'perpendicular':'parallel';
if(k==='properties')value=x*y;
if(k==='measure')value=x/4*y;
if(k==='reflection')value=x;
if(k==='sound')value=x*y>=20&&x*y<=20000?'inside':'outside';
if(k==='detection')value=x*y/2;
if(k==='spectrum')value=300/(x*y);
if(k==='refraction')value=b==='normal'?'none':a==='slower'?'toward':'away';
if(k==='hazards')value=x*y;
if(k==='applications')value=(a==='thermal'&&b==='ir')||(a==='internal'&&b==='xray')?'yes':'no';
if(k==='lenses')value=y/x;
if(k==='colour')value=a===b?a:'none';
if(k==='blackbody')value=a==='higher'?'shorter':'longer';
if(k==='infrared')value=(a==='matt'?20:5)*(b==='hot'?2:1);
return{value,a,b};}

export const predictionValid=(k,v,r)=>experimentOptions[k].choices?String(v)===String(r.value):numericWav1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>String(x[0])===String(v))?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
